function authorize(action) {
  return (req, res, next) => {
    const ability = req.ability ?? createAbilityFor(req.user);   // decision
    if (!ability.can(action, req.resource)) return res.sendStatus(403);
    next();                                                      // enforcement passes
  };
}

// loadArticle must set req.resource before the object-level decision
router.get('/articles/:id', loadArticle, authorize('read'), readArticle);
